package com.xenris.liquidwarsos;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.view.accessibility.*;import android.graphics.*;import java.io.*;import java.lang.reflect.*;import java.util.*;
import androidx.test.core.app.ActivityScenario;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.runner.lifecycle.*;import org.junit.*;import org.junit.runner.RunWith;import org.json.*;
import com.xenris.liquidwarsos.activities.GameActivity;import com.xenris.liquidwarsos.cloud.ModelMatch;
@RunWith(AndroidJUnit4.class) public class FreeLifecycleProbeTest {
 static Instrumentation i(){return InstrumentationRegistry.getInstrumentation();}static Context c(){return i().getTargetContext();}
 static Object f(Object o,String n)throws Exception{Field v=o.getClass().getDeclaredField(n);v.setAccessible(true);return v.get(o);}
 static void picture(String n)throws Exception{Bitmap b=i().getUiAutomation().takeScreenshot();try(OutputStream o=c().openFileOutput(n,0)){b.compress(Bitmap.CompressFormat.PNG,100,o);}b.recycle();}
 static void tap(Rect r){long t=SystemClock.uptimeMillis();float x=r.exactCenterX(),y=r.exactCenterY();MotionEvent a=MotionEvent.obtain(t,t,0,x,y,0),b=MotionEvent.obtain(t,t+40,1,x,y,0);a.setSource(4098);b.setSource(4098);Assert.assertTrue(i().getUiAutomation().injectInputEvent(a,true));Assert.assertTrue(i().getUiAutomation().injectInputEvent(b,true));a.recycle();b.recycle();}
 static void tap(View v){Rect r=new Rect();i().runOnMainSync(()->{int[] xy=new int[2];v.getLocationOnScreen(xy);r.set(xy[0],xy[1],xy[0]+v.getWidth(),xy[1]+v.getHeight());Assert.assertTrue(v.isShown());});tap(r);}
 static GameActivity resumed(){final GameActivity[] a={null};i().runOnMainSync(()->{for(Activity x:ActivityLifecycleMonitorRegistry.getInstance().getActivitiesInStage(Stage.RESUMED))if(x instanceof GameActivity)a[0]=(GameActivity)x;});return a[0];}
 static Intent start(boolean model){StaticBits.init();StaticBits.team=2;StaticBits.map=0;StaticBits.seed=924;StaticBits.dotsPerTeam=1000;StaticBits.timeLimit=model?120:2;StaticBits.alliances=AllianceRules.solo();return new Intent(c(),GameActivity.class).putExtra("qa_model_teams",model?4:0).putExtra("spectator",model).putExtra("qa_paid_budget",model).putExtra("qa_budget_ceiling_micros",8923724L).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);}
 @Test public void countdownPauseReplay()throws Exception{
  try(ActivityScenario<GameActivity> s=ActivityScenario.launch(start(false))){GameActivity a=resumed();Assert.assertNotNull(a);SystemClock.sleep(500);i().sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);SystemClock.sleep(400);Assert.assertTrue((Boolean)f(a,"paused"));int[] before=NativeInterface.modelSnapshot();SystemClock.sleep(1200);Assert.assertArrayEquals(before,NativeInterface.modelSnapshot());picture("lifecycle-paused-intro.png");AlertDialog d=(AlertDialog)f(a,"dialog");tap(d.getButton(-2));SystemClock.sleep(300);Assert.assertFalse((Boolean)f(a,"paused"));
   long end=SystemClock.elapsedRealtime()+9000;while(!(Boolean)f(a,"gameFinished")&&SystemClock.elapsedRealtime()<end)SystemClock.sleep(100);Assert.assertTrue((Boolean)f(a,"gameFinished"));picture("lifecycle-result.png");short[] old=NativeInterface.initialPositions();StaticBits.timeLimit=120;d=(AlertDialog)f(a,"dialog");tap(d.findViewById(R.id.result_primary));SystemClock.sleep(300);GameActivity b=resumed();for(int retry=0;retry<25&&(b==null||b==a);retry++){SystemClock.sleep(100);b=resumed();}Assert.assertNotNull(b);Assert.assertNotSame(a,b);Assert.assertEquals(0,b.getIntent().getIntExtra("qa_model_teams",63));Assert.assertFalse(Arrays.equals(old,NativeInterface.initialPositions()));ModelMatch m=(ModelMatch)f(f(b,"models"),"match");Assert.assertEquals(0,m.configuredMask());int[] warm=NativeInterface.modelSnapshot();SystemClock.sleep(600);Assert.assertArrayEquals(warm,NativeInterface.modelSnapshot());picture("lifecycle-replay-intro.png");final GameActivity ending=b;i().runOnMainSync(ending::finish);
  }
 }
 @Test public void budgetDeniedStopButton()throws Exception{
  File ledger=new File(c().getFilesDir(),"qa-strategy160-budget.json");JSONObject before=new JSONObject(new String(java.nio.file.Files.readAllBytes(ledger.toPath()),"UTF-8"));Assert.assertEquals(8923724L,before.getLong("reserved_or_peak_cost_micros"));
  try(ActivityScenario<GameActivity> s=ActivityScenario.launch(start(true))){GameActivity a=resumed();SystemClock.sleep(3700);Object support=f(a,"models");ModelMatch m=(ModelMatch)f(support,"match");Assert.assertEquals(4,m.configuredMask());short[][] xs=(short[][])f(a,"xs"),ys=(short[][])f(a,"ys");Assert.assertEquals(-2,xs[2][0]);Assert.assertEquals(-2,ys[2][0]);tap(a.findViewById(R.id.model_status));SystemClock.sleep(400);picture("lifecycle-stop-api-dialog.png");AccessibilityNodeInfo root=i().getUiAutomation().getRootInActiveWindow();java.util.List<AccessibilityNodeInfo> nodes=root.findAccessibilityNodeInfosByText("停止全部 API");if(nodes.isEmpty())nodes=root.findAccessibilityNodeInfosByText("Stop all APIs");Assert.assertFalse(nodes.isEmpty());Rect rect=new Rect();nodes.get(0).getBoundsInScreen(rect);tap(rect);SystemClock.sleep(500);Assert.assertTrue((Boolean)f(support,"closed"));Assert.assertEquals(0,m.inputs().mask);Assert.assertEquals(-2,xs[2][0]);picture("lifecycle-api-stopped.png");
  }
  JSONObject after=new JSONObject(new String(java.nio.file.Files.readAllBytes(ledger.toPath()),"UTF-8"));Assert.assertEquals(before.getInt("requests"),after.getInt("requests"));Assert.assertEquals(before.getLong("reserved_or_peak_cost_micros"),after.getLong("reserved_or_peak_cost_micros"));
 }
}
